using System.Text;
string file=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".bin");await File.WriteAllBytesAsync(file,new byte[10000]);
try{using var text=new MemoryStream();await Send("GET",200,new TextBody("Chào"),text,CancellationToken.None);Console.WriteLine("text:"+text.Length);
using var output=new MemoryStream();await Send("GET",200,new FileBody(file),output,CancellationToken.None);Console.WriteLine("file:"+output.Length);
using var head=new MemoryStream();await Send("HEAD",200,new TextBody("Chào"),head,CancellationToken.None);Console.WriteLine("head:"+head.Length);
using var empty=new MemoryStream();await Send("GET",204,new EmptyBody(),empty,CancellationToken.None);Console.WriteLine("empty:"+empty.Length);
using var cancel=new CancellationTokenSource();cancel.Cancel();try{await new FileBody(file).WriteAsync(output,cancel.Token);}catch(OperationCanceledException){Console.WriteLine("canceled");}}finally{File.Delete(file);}
static async Task Send(string method,int status,IResponseBodyWriter writer,Stream output,CancellationToken t){if(method=="HEAD"||status<200||status is 204 or 304)return;await writer.WriteAsync(output,t);}
interface IResponseBodyWriter{Task WriteAsync(Stream output,CancellationToken t);}
class TextBody(string text):IResponseBodyWriter{public Task WriteAsync(Stream output,CancellationToken t)=>output.WriteAsync(Encoding.UTF8.GetBytes(text),t).AsTask();}
class FileBody(string file):IResponseBodyWriter{public async Task WriteAsync(Stream output,CancellationToken t){await using var source=File.OpenRead(file);await source.CopyToAsync(output,t);}}
class EmptyBody:IResponseBodyWriter{public Task WriteAsync(Stream output,CancellationToken t)=>Task.CompletedTask;}

